pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address token, address[] memory tos, uint v, uint decimals) public {
        vm.assume(tos.length > 0);
        // bind decimals to avoid extreme exponent
        decimals = bound(decimals, 0, 18);
        // bind v to prevent overflow in v * 10**decimals
        v = bound(v, 0, type(uint).max / (10**bound(decimals, 0, 18)));

        // Deploy a minimal helper that acts as the token and always returns true
        SuccessToken helper = new SuccessToken();

        // The transfer function expects the token address as caddress
        bool ret = c.transfer(from, address(helper), tos, v, decimals);
        assertTrue(ret);
    }
}

contract SuccessToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

