// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v, uint256 _decimals) public {
        // 1. Restrict to admissible domain: avoid overflow in _value calculation
        vm.assume(v * 10 ** _decimals >= v);
        vm.assume(v * 10 ** _decimals / 10 ** _decimals == v);
        // 2. Call transfer and record revert status
        bool ok;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            ok = true;
        } catch {
            ok = false;
        }
        // 3. Assert: reference C reverts iff _tos is empty
        assertTrue(ok == (_tos.length > 0));
    }
}

