import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v, uint256 _decimals) public {
        vm.assume(_decimals <= 77);
        vm.assume(v * (10 ** _decimals) / (10 ** _decimals) == v);
        (bool succ,) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256,uint256)", from, caddress, _tos, v, _decimals));
        if (_tos.length > 0) {
            assertTrue(succ);
        } else {
            assertFalse(succ);
        }
    }
}

